            &crate::worker_run::VerifiedSessionResume,
            &crate::housekeeping::VerifiedDirectoryReuse,
        )>,
    ) -> Result<Permit> {
        self.admit_worker_context(
            lease,
            input,
            contract,
            WorkerAdmissionContext {
                planning: WorkerPlanning {
                    readmission,
