                            },
                            &std::collections::BTreeSet::from([actor]),
                            &Default::default(),
                            None,
                        )
                        .unwrap();
                }
                "inventory_changed" => {
                    parent.required_children.insert(Uuid::from_u128(8));
                }
                "config_changed" => revision = crate::digest::bytes_digest(b"new configuration"),
                _ => unreachable!(),
            }
            assert!(
                !evidence_projection_current(&gate, observed, &current, &revision, &fences, now),
                "{scenario}"
            );
        }
    }
}

//! Actual same-process registration observation. Diagnostic JSON never restores
//! an active registration or authorizes worker work.
use super::*;
use crate::evaluation::IndependentBoundaryIdentity;
impl RuntimeCoordinator {
    pub(super) fn observe_registered_independent_boundary(
        &self,
        control: &Arc<ControlHost>,
        permit: &Permit,
        contract: &Arc<WorkerContract>,
    ) -> Result<IndependentBoundaryIdentity> {
        if !Arc::ptr_eq(control, &self.control) {
            return Err(Error::new(
                "worker_binding",
                "independent observation belongs to another Control owner",
            ));
        }
        let mut observed = None;
        self.control.validate_permit(permit, || {
            self.registration.verify_active_owner(&permit.lease)?;
            let (actual, budget) = {
                let state = self.state.lock().map_err(|_| {
                    Error::new("runtime_unavailable", "boundary registration lock failed")
                })?;
                let run = state.runs.get(&permit.operation_id).ok_or_else(|| {
                    Error::new(
                        "worker_binding",
                        "independent observation has no actual registered operation",
                    )
                })?;
                if run.joined
                    || run._active.is_none()
                    || !Arc::ptr_eq(&run.contract, contract)
                    || canonical_digest(1, &run.permit)? != canonical_digest(1, permit)?
                {
                    return Err(Error::new(
                        "worker_binding",
                        "independent observation lost its original active registration",
                    ));
                }
                (run.contract.clone(), run.budget.clone())
            };
            // Independent only: no general delivery evidence, network or nested Control.
            let WorkerAuthority::Independent(original) = actual.authority() else {
                return Err(Error::new(
                    "worker_binding",
                    "registered worker has another authority kind",
                ));
            };
            let request_digest = boundary_model_request(&self.control, permit, &budget)?;
            let current = self.observations.active_independent_gate(original)?;
            observed =
                Some(actual.independent_boundary_identity(permit, request_digest, &current)?);
            Ok(())
        })?;
        observed.ok_or_else(|| {
            Error::new(
                "boundary_observation_unavailable",
                "serialized independent observation was not collected",
            )
        })
    }
}
/// Caller holds the actual permit gate. Reads protected bytes only; no nested
/// snapshot, serialization, raw marker-to-capability conversion or write.
fn boundary_model_request(
    control: &ControlHost,
    permit: &Permit,
    budget: &RunReference,
) -> Result<String> {
    if budget.phase.phase != "independent_review" || budget.phase.retry_grant.is_some() {
        return Err(Error::new(
            "boundary_observation_unavailable",
            "independent diagnostic requires its original ordinary model admission",
        ));
    }
    let expected = crate::control::ordinary_run_request_digest(permit, budget)?;
    let actual = control.operation(permit.operation_id)?;
    if crate::control::receipt_request_digest(&actual)? != expected
        || actual.phase != crate::control::ReceiptPhase::Prepared
        || actual.observed_result.is_some()
    {
        return Err(Error::new(
            "worker_binding",
            "independent immutable model admission changed",
        ));
    }
    Ok(expected)
}
#[cfg(test)]
#[path = "runtime_worker_boundary_tests.rs"]
mod tests;

use super::*;
use crate::control::{Actor, Lifecycle, MutationRequest, RunAdmission};

#[test]
fn actual_model_request_observation_retains_pause_and_refuses_change_fence_or_missing_bytes() {
    // Real protected Control/admission component only. No worker registration,
    // native process, active snapshot or MatchedAtCollection value is invented.
    let root = tempfile::tempdir().unwrap();
    let directory =
        PrivateDir::create(&root.path().canonicalize().unwrap().join("control")).unwrap();
    let receipts = directory.child("receipts").unwrap();
    let runtime = Uuid::new_v4();
    let host = ControlHost::setup(directory, runtime, Uuid::new_v4()).unwrap();
    let command = |kind: &str| MutationRequest {
        request_id: Uuid::new_v4(),
        runtime_id: runtime,
        actor: Actor {
            identity: "component operator".into(),
            principal: None,
            roles: BTreeSet::from(["lifecycle".into()]),
        },
        kind: kind.into(),
        canonical_targets: vec![runtime.to_string()],
        expected: BTreeMap::new(),
        payload: Value::Null,
    };
    host.lifecycle(command("start"), Lifecycle::Start, 0)
        .unwrap();
    let lease = Lease {
        runtime_id: runtime,
        owner_generation: 1,
        owner_id: Uuid::new_v4(),
    };
    host.attach_reconciled(lease.clone()).unwrap();
    let budget = RunReference {
        workspace: Uuid::new_v4(),
        account: "component account".into(),
        normalized_state: None,
        phase: crate::scheduler::PhaseKey {
            work: "component independent PR".into(),
            generation: bytes_digest(b"generation"),
            phase: "independent_review".into(),
            retry_grant: None,
        },
        profile_digest: bytes_digest(b"profile"),
        instruction_digest: bytes_digest(b"instructions"),
        max_attempts: 2,
        max_turns: 3,
        max_review_rounds: 1,
        attempt: 1,
    };
    let permit = host
        .admit_run(
            &lease,
            RunAdmission {
                request_id: Uuid::new_v4(),
                work_key: budget.phase.work.clone(),
                scope_digest: bytes_digest(b"scope"),
                reference: budget.clone(),
            },
            || Ok(()),
        )
        .unwrap();
    let check = |permit: &Permit, budget: &RunReference| {
        host.validate_permit(permit, || {
            boundary_model_request(&host, permit, budget)?;
            Ok(())
        })
    };
    check(&permit, &budget).unwrap();
    let original = host.operation(permit.operation_id).unwrap();
    let mut changed_budget = budget.clone();
    changed_budget.max_turns += 1;
    assert_eq!(
        check(&permit, &changed_budget).unwrap_err().code,
        "worker_binding"
    );
    let leaf = format!("{}.json", permit.operation_id);
    let bytes = receipts.read_bytes(&leaf, 256 * 1024).unwrap();
    let mut changed = original.clone();
    changed.actor = "substituted owner".into();
    receipts.write(&leaf, &changed).unwrap();
    assert_eq!(check(&permit, &budget).unwrap_err().code, "worker_binding");
    receipts.write_bytes(&leaf, &bytes).unwrap();
    std::fs::remove_file(receipts.path().join(&leaf)).unwrap();
    assert_eq!(check(&permit, &budget).unwrap_err().code, "record_missing");
    receipts.write_bytes(&leaf, &bytes).unwrap();
    assert_eq!(
        canonical_digest(1, &host.operation(permit.operation_id).unwrap()).unwrap(),
        canonical_digest(1, &original).unwrap()
    );
    host.lifecycle(
        command("pause"),
        Lifecycle::Pause,
        host.snapshot().unwrap().intent.generation,
    )
    .unwrap();
    assert!(!host.snapshot().unwrap().admission_open);
    check(&permit, &budget).unwrap();
    host.fence(permit.operation_id).unwrap();
    let mut callback_ran = false;
    assert!(
        host.validate_permit(&permit, || {
            callback_ran = true;
            Ok(())
        })
        .is_err()
    );
    assert!(
        !callback_ran,
        "a fenced permit must never reach diagnostic collection"
    );
}

