#[test]
fn structured_review_accepts_precise_blob_links_but_rejects_wrong_link_identity() {
    // Grader data only. No URL is fetched and no access/publication is established.
    let variant = suite()
        .variants
        .into_iter()
        .find(|v| v.id == "seeded")
        .unwrap();
    let (_temp, fixture, isolation, _) = setup(&variant);
    let original = good(&fixture, &trace("seeded"));
    let scorer = scorer(&variant);
    let repository = ReviewSourceRepository {
        hostname: "github.com".into(),
        id: "42".into(),
        slug: Some("owner/repo".into()),
    };
    let prose =
        |url: &str| format!("{url}: equal values are rejected; use <= for the inclusive boundary.");
    for revision in [&original.revision[..], &original.revision[..7]] {
        let mut facts = original.clone();
        let review = facts.review_claim.as_mut().unwrap();
        review.repository = Some(repository.clone());
        review.claim.unresolved_findings[0] = prose(&format!(
            "https://github.com/owner/repo/blob/{revision}/src/limit.py#L2"
        ));
        assert!(
            grade(
                &scorer,
                &fixture,
                &isolation,
                &facts,
                &variant.prohibited_effects
            )
            .unwrap()
            .deterministic_pass
        );
    }
    let suffix = format!("blob/{}/src/limit.py#L2", original.revision);
    for url in [
        format!(
            "https://github.com/owner/repo/blob/{}/src/limit.py#L2",
            "f".repeat(40)
        ),
        format!(
            "https://github.com/owner/repo/blob/{}/other/src/limit.py#L2",
            original.revision
        ),
        format!("https://github.com/owner/other/{suffix}"),
        format!("https://foreign.invalid/owner/repo/{suffix}"),
        format!("https://user@github.com/owner/repo/{suffix}"),
        format!(
            "https://github.com/owner/repo/blob/{}/src/limit.py#L3",
            original.revision
        ),
        format!(
            "https://github.com/owner/repo/blob/{}/src%2Flimit.py#L2",
            original.revision
        ),
        "https://github.com/owner/repo/blob/123456/src/limit.py#L2".into(),
    ] {
        let mut facts = original.clone();
        let review = facts.review_claim.as_mut().unwrap();
        review.repository = Some(repository.clone());
        review.claim.unresolved_findings[0] = prose(&url);
        assert!(
            !grade(
                &scorer,
                &fixture,
                &isolation,
                &facts,
                &variant.prohibited_effects
            )
            .unwrap()
            .deterministic_pass,
            "{url}"
        );
    }
    let mut unknown_repository = original.clone();
    unknown_repository
        .review_claim
        .as_mut()
        .unwrap()
        .claim
        .unresolved_findings[0] = prose(&format!("https://github.com/owner/repo/{suffix}"));
    assert!(
        unknown_repository
            .review_claim
            .as_ref()
            .unwrap()
            .repository
            .is_none()
    );
    let result = grade(
        &scorer,
        &fixture,
        &isolation,
        &unknown_repository,
        &variant.prohibited_effects,
    )
    .unwrap();
    assert!(result.deterministic_pass);
    assert!(result.human_review.starts_with("pending"));
}

use kegari_v0::{digest::bytes_digest, evaluation::*, evaluation_reports::*};
use serde_json::{Value, json};
use std::{
    fs,
    os::unix::fs::{MetadataExt, symlink},
    path::PathBuf,
    process::Command,
};

fn suite() -> SuiteManifest {
    SuiteManifest::load(
        &PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("evaluations/manifest.json"),
    )
    .unwrap()
}
fn archive(suite: &SuiteManifest) -> (tempfile::TempDir, ReportStore) {
    let temp = tempfile::tempdir().unwrap();
    let store =
        ReportStore::create(&temp.path().canonicalize().unwrap().join("reports"), suite).unwrap();
    (temp, store)
}
fn report(suite: &SuiteManifest, outcome: TrialOutcome) -> TrialReport {
    let key = suite.plan().unwrap()[0].clone();
    let variant = suite
        .variants
        .iter()
        .find(|v| v.id == key.variant && v.case_id == key.case_id)
        .unwrap();
    let mut r = TrialReport::unrun(
        suite,
        variant,
        key,
        TrialOutcome::Blocked,
        "deterministic report-reader fixture",
    )
    .unwrap();
    r.outcome = outcome;
    r.evidence_class = EvidenceClass::DeterministicReplay;
    if r.outcome == TrialOutcome::DeterministicPassHumanPending {
        r.grade = Some(Grade {
            assertions: variant
                .expected_outcomes
                .iter()
                .map(String::as_str)
                .chain([
                    "runtime_scope",
                    "prohibited_effects",
                    "actual_candidate_provenance",
                ])
                .map(|id| AssertionResult {
                    id: id.into(),
                    passed: true,
                    detail: "reader fixture, not agent evidence".into(),
                })
                .collect(),
            deterministic_pass: true,
            human_review: "pending".into(),
        });
    }
    r
}

#[test]
fn declared_success_cannot_omit_duplicate_or_contradict_grading_predicates() {
    let suite = suite();
    for invalid in ["omit", "duplicate", "contradict"] {
        let (_temp, store) = archive(&suite);
        let mut r = report(&suite, TrialOutcome::DeterministicPassHumanPending);
        let grade = r.grade.as_mut().unwrap();
        match invalid {
            "omit" => {
                grade.assertions.pop();
            }
            "duplicate" => grade.assertions.push(grade.assertions[0].clone()),
            _ => grade.deterministic_pass = false,
        }
        store.finish(&r).unwrap();
        assert_eq!(
            ReportArchive::open(store.root()).err().unwrap().code,
            "evaluation_record_conflict",
            "{invalid}"
        );
    }
}

